package com.osrscoach;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(CoachConfig.GROUP)
public interface CoachConfig extends Config
{
	String GROUP = "osrscoach";

	enum Provider
	{
		MOCK,
		ANTHROPIC,
		OPENAI_COMPATIBLE
	}

	enum WebSearch
	{
		OFF,
		SERPER_GOOGLE,
		BRAVE
	}

	enum TextSize
	{
		SMALL(13),
		MEDIUM(16),
		LARGE(19),
		HUGE(23);

		public final int points;

		TextSize(int points)
		{
			this.points = points;
		}
	}

	enum Membership
	{
		AUTO_DETECT,
		FREE_TO_PLAY,
		MEMBER
	}

	@ConfigSection(name = "AI provider", description = "Which AI service answers your questions", position = 0)
	String providerSection = "provider";

	@ConfigSection(name = "Backup AI providers", description = "Used automatically when the main provider is rate limited, out of credit or down",
		position = 1, closedByDefault = true)
	String backupSection = "backup";

	@ConfigSection(name = "Context sent to AI", description = "Choose which account details may be sent with a question", position = 2)
	String contextSection = "context";

	@ConfigSection(name = "About me", description = "Things the game can't tell the coach", position = 3)
	String aboutSection = "about";

	@ConfigSection(name = "Behaviour", description = "Lookups, history and suggestions", position = 4)
	String behaviourSection = "behaviour";

	// ---------------- provider ----------------

	@ConfigItem(keyName = "provider", name = "Provider",
		description = "MOCK = offline rule-based placeholder (no AI). ANTHROPIC = Claude API. OPENAI_COMPATIBLE = OpenAI, OpenRouter, Ollama, LM Studio, etc.",
		section = providerSection, position = 0)
	default Provider provider()
	{
		return Provider.MOCK;
	}

	@ConfigItem(keyName = "apiKey", name = "API key",
		description = "Stored locally in your RuneLite settings. Never logged. Leave blank for local servers like Ollama.",
		secret = true, section = providerSection, position = 1)
	default String apiKey()
	{
		return "";
	}

	@ConfigItem(keyName = "model", name = "Model",
		description = "e.g. claude-sonnet-5-5 or claude-haiku-5-5 (Anthropic), gpt-4.1-mini (OpenAI), llama3.1 (Ollama). Must support tool calling for wiki lookups.",
		section = providerSection, position = 2)
	default String model()
	{
		return "claude-sonnet-5-5";
	}

	@ConfigItem(keyName = "baseUrl", name = "Base URL (OpenAI-compatible)",
		description = "Only for OPENAI_COMPATIBLE. e.g. https://api.openai.com/v1 or http://localhost:11434/v1",
		section = providerSection, position = 3)
	default String baseUrl()
	{
		return "https://api.openai.com/v1";
	}

	@ConfigItem(keyName = "maxTokens", name = "Max answer length (tokens)",
		description = "Upper bound on each answer. Lower = cheaper.", section = providerSection, position = 4)
	@Range(min = 200, max = 4000)
	default int maxTokens()
	{
		return 1200;
	}

	@ConfigItem(keyName = "backup1BaseUrl", name = "Backup 1: Base URL",
		description = "OpenAI-compatible URL, e.g. https://generativelanguage.googleapis.com/v1beta/openai/ (Gemini) or https://api.groq.com/openai/v1. Blank = off.",
		section = backupSection, position = 10)
	default String backup1BaseUrl()
	{
		return "";
	}

	@ConfigItem(keyName = "backup1ApiKey", name = "Backup 1: API key", description = "Stored locally, never logged.",
		secret = true, section = backupSection, position = 11)
	default String backup1ApiKey()
	{
		return "";
	}

	@ConfigItem(keyName = "backup1Model", name = "Backup 1: Model", description = "e.g. gemini-3.8-flash or openai/gpt-oss-120b",
		section = backupSection, position = 12)
	default String backup1Model()
	{
		return "";
	}

	@ConfigItem(keyName = "backup2BaseUrl", name = "Backup 2: Base URL",
		description = "OpenAI-compatible URL, e.g. https://generativelanguage.googleapis.com/v1beta/openai/ (Gemini) or https://api.groq.com/openai/v1. Blank = off.",
		section = backupSection, position = 20)
	default String backup2BaseUrl()
	{
		return "";
	}

	@ConfigItem(keyName = "backup2ApiKey", name = "Backup 2: API key", description = "Stored locally, never logged.",
		secret = true, section = backupSection, position = 21)
	default String backup2ApiKey()
	{
		return "";
	}

	@ConfigItem(keyName = "backup2Model", name = "Backup 2: Model", description = "e.g. gemini-3.8-flash or openai/gpt-oss-120b",
		section = backupSection, position = 22)
	default String backup2Model()
	{
		return "";
	}

	// ---------------- context toggles ----------------

	@ConfigItem(keyName = "sendSkills", name = "Skills & XP", description = "Send skill levels and experience", section = contextSection, position = 0)
	default boolean sendSkills()
	{
		return true;
	}

	@ConfigItem(keyName = "sendQuests", name = "Quest progress", description = "Send quest states", section = contextSection, position = 1)
	default boolean sendQuests()
	{
		return true;
	}

	@ConfigItem(keyName = "sendInventory", name = "Inventory", description = "Send carried items", section = contextSection, position = 2)
	default boolean sendInventory()
	{
		return true;
	}

	@ConfigItem(keyName = "sendEquipment", name = "Equipment", description = "Send worn items", section = contextSection, position = 3)
	default boolean sendEquipment()
	{
		return true;
	}

	@ConfigItem(keyName = "sendLocation", name = "Location", description = "Send your tile coordinates", section = contextSection, position = 4)
	default boolean sendLocation()
	{
		return true;
	}

	@ConfigItem(keyName = "sendAccountType", name = "Account type & world", description = "Send ironman mode and members/F2P world", section = contextSection, position = 5)
	default boolean sendAccountType()
	{
		return true;
	}

	@ConfigItem(keyName = "sendBank", name = "Bank (cached)",
		description = "Send the bank snapshot cached the last time you opened your bank this session. Off by default.",
		section = contextSection, position = 6)
	default boolean sendBank()
	{
		return false;
	}

	@ConfigItem(keyName = "sendProfile", name = "My goals, budget & notes", description = "Send what you typed in 'About me'", section = contextSection, position = 7)
	default boolean sendProfile()
	{
		return true;
	}

	// ---------------- about me ----------------

	@ConfigItem(keyName = "membership", name = "Membership", description = "Override if auto-detect is wrong", section = aboutSection, position = 0)
	default Membership membership()
	{
		return Membership.AUTO_DETECT;
	}

	@ConfigItem(keyName = "budget", name = "Budget", description = "Free text, e.g. '500k gp'. The coach never guesses this from your inventory.", section = aboutSection, position = 1)
	default String budget()
	{
		return "";
	}

	@ConfigItem(keyName = "goals", name = "Goals", description = "e.g. 'Get a fire cape eventually; enjoy questing'", section = aboutSection, position = 2)
	default String goals()
	{
		return "";
	}

	@ConfigItem(keyName = "preferences", name = "Preferences", description = "e.g. 'I like skilling more than combat; 1 hour a day'", section = aboutSection, position = 3)
	default String preferences()
	{
		return "";
	}

	// ---------------- behaviour ----------------

	@ConfigItem(keyName = "stepByStep", name = "Step-by-step answers",
		description = "Answer as short numbered in-game steps; press 'Done → next step' to continue",
		section = behaviourSection, position = -2)
	default boolean stepByStep()
	{
		return true;
	}

	@ConfigItem(keyName = "textSize", name = "Chat text size", description = "Size of the coach's chat text",
		section = behaviourSection, position = -1)
	default TextSize textSize()
	{
		return TextSize.LARGE;
	}

	@ConfigItem(keyName = "wikiLookups", name = "Allow wiki & price lookups",
		description = "Lets the coach search the OSRS Wiki and read real-time prices from prices.runescape.wiki",
		section = behaviourSection, position = 0)
	default boolean wikiLookups()
	{
		return true;
	}

	@ConfigItem(keyName = "webSearch", name = "General web search",
		description = "Lets the coach search the whole web for things the wiki lacks (updates, Reddit, guides). "
			+ "SERPER_GOOGLE = real Google results (serper.dev). BRAVE = Brave Search API. Needs its own key below.",
		section = behaviourSection, position = 1)
	default WebSearch webSearch()
	{
		return WebSearch.OFF;
	}

	@ConfigItem(keyName = "webSearchKey", name = "Web search API key",
		description = "Key from serper.dev or api-dashboard.search.brave.com. Stored locally, never logged.",
		secret = true, section = behaviourSection, position = 2)
	default String webSearchKey()
	{
		return "";
	}

	@ConfigItem(keyName = "compactMode", name = "Compact mode (free tiers)",
		description = "Shorter wiki pages and fewer lookups per answer, for free plans with low tokens-per-minute limits. "
			+ "Always on automatically for Groq.",
		section = behaviourSection, position = 3)
	default boolean compactMode()
	{
		return false;
	}

	@ConfigItem(keyName = "historyTurns", name = "Remembered turns", description = "How many previous Q&A pairs are re-sent for context", section = behaviourSection, position = 4)
	@Range(min = 0, max = 20)
	default int historyTurns()
	{
		return 6;
	}

	@ConfigItem(keyName = "mapMarkers", name = "Mark destinations on map",
		description = "Let the coach pin where you need to go on the world map, point the yellow hint arrow at it, "
			+ "and draw a route if you use the Shortest Path plugin. Visual only.",
		section = behaviourSection, position = 6)
	default boolean mapMarkers()
	{
		return true;
	}

	@ConfigItem(keyName = "openOnStartup", name = "Open coach on startup",
		description = "Open the OSRS Coach panel automatically when RuneLite starts",
		section = behaviourSection, position = 7)
	default boolean openOnStartup()
	{
		return true;
	}

	@ConfigItem(keyName = "proactive", name = "Quest-complete suggestions",
		description = "When you finish a quest, show ONE quiet prompt in the panel. No popups or notifications.",
		section = behaviourSection, position = 5)
	default boolean proactive()
	{
		return false;
	}
}

package com.osrscoach;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.osrscoach.ai.CoachService;
import com.osrscoach.ai.MapMarker;
import com.osrscoach.context.AccountSnapshot;
import com.osrscoach.context.Availability;
import com.osrscoach.context.BankCache;
import com.osrscoach.context.ContextCollector;
import com.osrscoach.research.WikiClient;
import com.osrscoach.ui.CoachPanel;
import java.awt.image.BufferedImage;
import java.time.Clock;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "OSRS Coach",
	description = "Beginner AI coach: reads your account, suggests one next step, cites the OSRS Wiki",
	tags = {"ai", "coach", "beginner", "guide", "quest", "help"}
)
public class CoachPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private ConfigManager configManager;
	@Inject
	private CoachConfig config;
	@Inject
	private OkHttpClient okHttpClient;
	@Inject
	private Gson gson;
	@Inject
	private ContextCollector collector;
	@Inject
	private BankCache bankCache;
	@Inject
	private ClientThread clientThread;
	@Inject
	private WorldMapPointManager worldMapPointManager;
	@Inject
	private EventBus eventBus;

	private volatile WorldMapPoint markerPoint;
	private volatile WorldPoint markerTarget;
	private BufferedImage markerIcon;

	private ScheduledExecutorService executor;
	private CoachService service;
	private CoachPanel panel;
	private NavigationButton navButton;
	private volatile String selectedQuest;
	private final Set<String> finishedSeen = new HashSet<>();
	private final Set<String> notified = new HashSet<>();
	private boolean baselineTaken;

	@Provides
	CoachConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CoachConfig.class);
	}

	@Override
	protected void startUp()
	{
		executor = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread t = new Thread(r, "osrs-coach");
			t.setDaemon(true);
			return t;
		});
		WikiClient wiki = new WikiClient(okHttpClient, gson);
		service = new CoachService(collector::collect, () -> config, () -> selectedQuest, okHttpClient, gson, wiki, executor, Clock.systemUTC());

		List<String> quests = new ArrayList<>();
		for (Quest q : Quest.values())
		{
			quests.add(q.getName());
		}
		quests.sort(String::compareToIgnoreCase);
		List<String> skills = new ArrayList<>();
		for (Skill s : Skill.values())
		{
			if (!"Overall".equals(s.getName()))
			{
				skills.add(s.getName());
			}
		}

		markerIcon = ImageUtil.loadImageResource(getClass(), "marker.png");
		service.setMarker(new MapMarker()
		{
			@Override
			public void mark(String label, int x, int y, int plane)
			{
				clientThread.invoke(() -> placeMarker(label, new WorldPoint(x, y, plane)));
			}

			@Override
			public void clear()
			{
				clientThread.invoke(CoachPlugin.this::clearMarker);
			}
		});

		panel = new CoachPanel(service, () -> config, configManager, quests, skills, q -> selectedQuest = q,
			() -> clientThread.invoke(this::clearMarker));
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder().tooltip("OSRS Coach").icon(icon).priority(1).panel(panel).build();
		clientToolbar.addNavigation(navButton);
		if (config.openOnStartup())
		{
			javax.swing.SwingUtilities.invokeLater(() -> clientToolbar.openPanel(navButton));
		}

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			refreshAndDetect();
		}
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(this::clearMarker);
		clientToolbar.removeNavigation(navButton);
		executor.shutdownNow();
		bankCache.clear();
		finishedSeen.clear();
		notified.clear();
		baselineTaken = false;
		panel = null;
		service = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			refreshAndDetect();
		}
		else if (e.getGameState() == GameState.LOGIN_SCREEN)
		{
			// Could be a different account next: drop per-account caches.
			bankCache.clear();
			finishedSeen.clear();
			baselineTaken = false;
			if (panel != null)
			{
				panel.showContext(AccountSnapshot.loggedOut(java.time.Instant.now()));
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		// Fires on the client thread when the bank is open; we only cache what the client already shows the player.
		// Nothing is cached unless the player opted in to sharing bank context.
		if (config.sendBank() && e.getContainerId() == InventoryID.BANK && e.getItemContainer() != null)
		{
			bankCache.update(collector.toStacks(e.getItemContainer().getItems(), false), java.time.Instant.now());
		}
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		WorldPoint target = markerTarget;
		if (target == null || client.getLocalPlayer() == null)
		{
			return;
		}
		WorldPoint me = client.getLocalPlayer().getWorldLocation();
		if (me != null && me.getPlane() == target.getPlane() && me.distanceTo2D(target) <= 3)
		{
			clearMarker();
			if (panel != null)
			{
				panel.showArrived();
			}
		}
	}

	/** Client thread. Draws only: world map pin, hint arrow, optional Shortest Path route. */
	private void placeMarker(String label, WorldPoint wp)
	{
		clearMarker();
		WorldMapPoint p = WorldMapPoint.builder()
			.worldPoint(wp)
			.image(markerIcon)
			.name("Coach: " + label)
			.tooltip("Coach: " + label)
			.snapToEdge(true)
			.jumpOnClick(true)
			.build();
		worldMapPointManager.add(p);
		markerPoint = p;
		markerTarget = wp;
		client.setHintArrow(wp);
		Map<String, Object> data = new java.util.HashMap<>();
		if (client.getLocalPlayer() != null)
		{
			data.put("start", client.getLocalPlayer().getWorldLocation());
		}
		data.put("target", wp);
		eventBus.post(new PluginMessage("shortestpath", "path", data));
		if (panel != null)
		{
			panel.showMarker(label);
		}
	}

	/** Client thread. Removes only what the coach placed. */
	void clearMarker()
	{
		WorldMapPoint p = markerPoint;
		WorldPoint target = markerTarget;
		if (p != null)
		{
			worldMapPointManager.remove(p);
		}
		if (target != null)
		{
			if (client.hasHintArrow() && target.equals(client.getHintArrowPoint()))
			{
				client.clearHintArrow();
			}
			eventBus.post(new PluginMessage("shortestpath", "clear"));
		}
		markerPoint = null;
		markerTarget = null;
		if (panel != null)
		{
			panel.showMarker(null);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		if (!config.proactive() || e.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String m = e.getMessage().toLowerCase();
		if (m.contains("completed a quest") || m.contains("quest complete"))
		{
			// The message text is only a hint; the quest-state diff decides.
			refreshAndDetect();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (CoachConfig.GROUP.equals(e.getGroup()) && panel != null)
		{
			panel.updateProviderLabel();
			panel.applyTextSize();
			if (service != null)
			{
				service.resetCooldowns();
			}
		}
	}

	private void refreshAndDetect()
	{
		if (service == null)
		{
			return;
		}
		service.refresh().thenAccept(snap ->
		{
			if (panel == null)
			{
				return;
			}
			panel.showContext(snap);
			detectFinishedQuests(snap);
		});
	}

	/** Runs on the coach worker thread. Shows at most one quiet banner per finished quest per session. */
	private synchronized void detectFinishedQuests(AccountSnapshot snap)
	{
		if (!snap.isLoggedIn() || snap.getQuestsAvailability() != Availability.AVAILABLE)
		{
			return;
		}
		Set<String> nowFinished = new HashSet<>();
		for (Map.Entry<String, String> q : snap.getQuests().entrySet())
		{
			if ("FINISHED".equals(q.getValue()))
			{
				nowFinished.add(q.getKey());
			}
		}
		if (baselineTaken && config.proactive())
		{
			for (String q : nowFinished)
			{
				if (!finishedSeen.contains(q) && notified.add(q))
				{
					panel.showQuestCompleted(q);
					break;
				}
			}
		}
		finishedSeen.clear();
		finishedSeen.addAll(nowFinished);
		baselineTaken = true;
	}
}

package com.osrscoach.ai;

public interface AiProvider
{
	/** Blocking. Call off the client and Swing threads. */
	CoachReply respond(CoachRequest request, CoachTools tools) throws CoachException;

	String label();
}

package com.osrscoach.ai;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.LinkedHashMap;
import java.util.Map;
import okhttp3.OkHttpClient;

/** Claude Messages API with client-side tools (our wiki/price lookups). */
public class AnthropicProvider implements AiProvider
{
	static final String DEFAULT_URL = "https://api.anthropic.com/v1/messages";
	static final int MAX_ROUNDS = 5;

	private final OkHttpClient http;
	private final Gson gson;
	private final String apiKey;
	private final String url;

	public AnthropicProvider(OkHttpClient http, Gson gson, String apiKey)
	{
		this(http, gson, apiKey, DEFAULT_URL);
	}

	AnthropicProvider(OkHttpClient http, Gson gson, String apiKey, String url)
	{
		this.http = http;
		this.gson = gson;
		this.apiKey = apiKey;
		this.url = url;
	}

	@Override
	public String label()
	{
		return "Claude (Anthropic API)";
	}

	@Override
	public CoachReply respond(CoachRequest req, CoachTools tools) throws CoachException
	{
		String key = Secrets.cleanKey(apiKey);
		if (key.isEmpty())
		{
			throw new CoachException(CoachException.Kind.NO_CREDENTIALS, "Add your Anthropic API key in the plugin settings, or switch Provider to MOCK.", false);
		}
		Map<String, String> headers = new LinkedHashMap<>();
		headers.put("x-api-key", key);
		headers.put("anthropic-version", "2023-06-01");

		JsonArray messages = new JsonArray();
		for (ChatTurn t : req.getHistory())
		{
			messages.add(textMessage(t.getRole() == ChatTurn.Role.USER ? "user" : "assistant", t.getText()));
		}
		messages.add(textMessage("user", req.getUserMessage()));

		JsonArray toolDefs = new JsonArray();
		for (CoachTools.Spec s : tools.specs())
		{
			JsonObject d = new JsonObject();
			d.addProperty("name", s.name);
			d.addProperty("description", s.description);
			d.add("input_schema", s.schema);
			toolDefs.add(d);
		}

		int maxRounds = req.isCompact() ? 3 : MAX_ROUNDS;
		for (int round = 0; round <= maxRounds; round++)
		{
			JsonObject body = new JsonObject();
			body.addProperty("model", req.getModel());
			body.addProperty("max_tokens", req.getMaxTokens());
			body.addProperty("system", req.getSystemPrompt());
			body.add("messages", messages);
			if (toolDefs.size() > 0)
			{
				body.add("tools", toolDefs);
				if (round == maxRounds)
				{
					JsonObject none = new JsonObject();
					none.addProperty("type", "none");
					body.add("tool_choice", none);
				}
			}

			JsonObject res = HttpJson.post(http, gson, url, headers, body, "Anthropic");
			JsonArray content = res.has("content") && res.get("content").isJsonArray() ? res.getAsJsonArray("content") : null;
			if (content == null)
			{
				throw new CoachException(CoachException.Kind.INVALID_RESPONSE, "Anthropic response had no content.", true);
			}
			String stop = res.has("stop_reason") && !res.get("stop_reason").isJsonNull() ? res.get("stop_reason").getAsString() : "";

			if ("tool_use".equals(stop) && round < maxRounds)
			{
				JsonObject assistant = new JsonObject();
				assistant.addProperty("role", "assistant");
				assistant.add("content", content);
				messages.add(assistant);

				JsonArray results = new JsonArray();
				for (JsonElement el : content)
				{
					JsonObject block = el.getAsJsonObject();
					if (!"tool_use".equals(str(block, "type")))
					{
						continue;
					}
					JsonObject input = block.has("input") && block.get("input").isJsonObject() ? block.getAsJsonObject("input") : new JsonObject();
					JsonObject r = new JsonObject();
					r.addProperty("type", "tool_result");
					r.addProperty("tool_use_id", str(block, "id"));
					r.addProperty("content", tools.execute(str(block, "name"), input));
					results.add(r);
				}
				if (results.size() == 0)
				{
					throw new CoachException(CoachException.Kind.INVALID_RESPONSE, "Anthropic asked to use a tool but sent no tool call.", true);
				}
				JsonObject user = new JsonObject();
				user.addProperty("role", "user");
				user.add("content", results);
				messages.add(user);
				continue;
			}

			StringBuilder text = new StringBuilder();
			for (JsonElement el : content)
			{
				JsonObject block = el.isJsonObject() ? el.getAsJsonObject() : null;
				if (block != null && "text".equals(str(block, "type")) && block.has("text"))
				{
					text.append(block.get("text").getAsString());
				}
			}
			String out = text.toString().trim();
			if (out.isEmpty())
			{
				throw new CoachException(CoachException.Kind.INVALID_RESPONSE,
					"max_tokens".equals(stop) ? "The answer was cut off before any text. Raise 'Max answer length'." : "Anthropic returned an empty answer.", true);
			}
			if ("max_tokens".equals(stop))
			{
				out += "\n\n_(Answer cut off — raise 'Max answer length' in settings for longer replies.)_";
			}
			return new CoachReply(out, tools.sources(), tools.failures(), true, label() + " · " + req.getModel(), tools.marks());
		}
		throw new CoachException(CoachException.Kind.INVALID_RESPONSE, "The AI kept requesting lookups without answering.", true);
	}

	private static JsonObject textMessage(String role, String text)
	{
		JsonObject m = new JsonObject();
		m.addProperty("role", role);
		m.addProperty("content", text);
		return m;
	}

	private static String str(JsonObject o, String k)
	{
		return o.has(k) && o.get(k).isJsonPrimitive() ? o.get(k).getAsString() : "";
	}
}

