package com.osrscoach.ai;

import com.google.gson.JsonObject;
import com.osrscoach.context.AccountSnapshot;
import com.osrscoach.context.Availability;
import com.osrscoach.context.SkillInfo;
import java.util.Map;

/**
 * Offline placeholder used when no AI provider is configured. It does NOT understand questions;
 * it applies one fixed rule to the account context so the whole pipeline can be tried without a key.
 * Every reply is marked non-live and starts with a banner.
 */
public class MockProvider implements AiProvider
{
	public static final String BANNER = "⚠ **MOCK MODE — this is not AI output.** A fixed rule produced this from your account data; it did not read your question. Set a Provider and API key in settings for real answers.";

	private final AccountSnapshot snapshot;
	private final boolean questsShared;
	private final boolean skillsShared;

	public MockProvider(AccountSnapshot snapshot, boolean questsShared, boolean skillsShared)
	{
		this.snapshot = snapshot;
		this.questsShared = questsShared;
		this.skillsShared = skillsShared;
	}

	@Override
	public String label()
	{
		return "Mock mode (no AI)";
	}

	@Override
	public CoachReply respond(CoachRequest req, CoachTools tools)
	{
		String step;
		String why;
		String lookup;
		if (snapshot == null || !snapshot.isLoggedIn())
		{
			step = "Log in, then press **Refresh** so the coach can read your account.";
			why = "Without live data, any advice would be a guess.";
			lookup = null;
		}
		else
		{
			String inProgress = questsShared ? firstInProgress(snapshot) : null;
			SkillInfo lowest = skillsShared ? lowestFreeSkill(snapshot) : null;
			if (inProgress != null)
			{
				step = "Continue **" + inProgress + "** (it's already in progress).";
				why = "Finishing started quests gives quest points and rewards without new requirements to chase.";
				lookup = inProgress;
			}
			else if (lowest != null)
			{
				step = "Train **" + lowest.getName() + "** (your lowest free-to-play skill, level " + lowest.getLevel() + ").";
				why = "Raising your lowest skill opens more quests and training options.";
				lookup = lowest.getName();
			}
			else
			{
				step = "Share skills or quests in settings so the mock rule has something to work with.";
				why = "Both are unavailable or switched off.";
				lookup = null;
			}
		}

		StringBuilder sb = new StringBuilder(BANNER).append("\n\n");
		sb.append("**Next step:** ").append(step).append('\n');
		sb.append("**Why:** ").append(why).append('\n');
		sb.append("**How to start:** Open the OSRS Wiki page below; Quest Helper can guide quest steps.\n");
		if (lookup != null && tools.enabled())
		{
			JsonObject args = new JsonObject();
			args.addProperty("query", lookup);
			String res = tools.execute("wiki_search", args);
			if (res.startsWith("LOOKUP_FAILED") || res.startsWith("LOOKUP_UNAVAILABLE"))
			{
				sb.append("\n_Wiki lookup failed, so nothing here was verified._\n");
			}
		}
		else if (lookup != null)
		{
			sb.append("\n_Wiki lookups are off, so nothing here was verified._\n");
		}
		sb.append("**Sources:** ").append(tools.sources().isEmpty() ? "none (mock mode)" : "see the verified links below — fetched live from the wiki") .append('\n');
		return new CoachReply(sb.toString(), tools.sources(), tools.failures(), false, label(), tools.marks());
	}

	static String firstInProgress(AccountSnapshot s)
	{
		if (s.getQuestsAvailability() != Availability.AVAILABLE)
		{
			return null;
		}
		for (Map.Entry<String, String> e : s.getQuests().entrySet())
		{
			if ("IN_PROGRESS".equals(e.getValue()))
			{
				return e.getKey();
			}
		}
		return null;
	}

	static SkillInfo lowestFreeSkill(AccountSnapshot s)
	{
		if (s.getSkillsAvailability() != Availability.AVAILABLE)
		{
			return null;
		}
		SkillInfo best = null;
		for (SkillInfo si : s.getSkills())
		{
			if (!si.isMembersOnly() && (best == null || si.getXp() < best.getXp()))
			{
				best = si;
			}
		}
		return best;
	}
}

package com.osrscoach.ai;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import java.util.LinkedHashMap;
import java.util.Map;
import okhttp3.OkHttpClient;

/**
 * Chat Completions API as implemented by OpenAI, OpenRouter, Ollama, LM Studio and others.
 * Uses function calling for lookups; models without tool support should get lookups disabled.
 */
public class OpenAiCompatibleProvider implements AiProvider
{
	static final int MAX_ROUNDS = 5;

	private final OkHttpClient http;
	private final Gson gson;
	private final String apiKey;
	private final String baseUrl;

	public OpenAiCompatibleProvider(OkHttpClient http, Gson gson, String apiKey, String baseUrl)
	{
		this.http = http;
		this.gson = gson;
		this.apiKey = apiKey;
		this.baseUrl = Secrets.cleanUrl(baseUrl);
	}

	@Override
	public String label()
	{
		return "OpenAI-compatible (" + host() + ")";
	}

	private String host()
	{
		String s = baseUrl.replaceFirst("^https?://", "");
		int i = s.indexOf('/');
		return i < 0 ? s : s.substring(0, i);
	}

	@Override
	public CoachReply respond(CoachRequest req, CoachTools tools) throws CoachException
	{
		if (!baseUrl.startsWith("http://") && !baseUrl.startsWith("https://"))
		{
			throw new CoachException(CoachException.Kind.BAD_CONFIG, "Set 'Base URL' to something like https://api.openai.com/v1 or http://localhost:11434/v1", false);
		}
		boolean local = baseUrl.contains("://localhost") || baseUrl.contains("://127.0.0.1");
		String key = Secrets.cleanKey(apiKey);
		if (key.isEmpty() && !local)
		{
			throw new CoachException(CoachException.Kind.NO_CREDENTIALS, "Add an API key for " + host() + " in the plugin settings, or switch Provider to MOCK.", false);
		}
		Map<String, String> headers = new LinkedHashMap<>();
		if (!key.isEmpty())
		{
			headers.put("Authorization", "Bearer " + key);
		}

		JsonArray messages = new JsonArray();
		messages.add(msg("system", req.getSystemPrompt()));
		for (ChatTurn t : req.getHistory())
		{
			messages.add(msg(t.getRole() == ChatTurn.Role.USER ? "user" : "assistant", t.getText()));
		}
		messages.add(msg("user", req.getUserMessage()));

		JsonArray toolDefs = new JsonArray();
		for (CoachTools.Spec s : tools.specs())
		{
			JsonObject fn = new JsonObject();
			fn.addProperty("name", s.name);
			fn.addProperty("description", s.description);
			fn.add("parameters", s.schema);
			JsonObject d = new JsonObject();
			d.addProperty("type", "function");
			d.add("function", fn);
			toolDefs.add(d);
		}

		int maxRounds = req.isCompact() ? 3 : MAX_ROUNDS;
		boolean useCompletionTokens = host().equals("api.openai.com");
		boolean switchedTokenParam = false;
		// One extra round: after the lookup budget is spent the model gets "answer now" tool results,
		// because some providers (e.g. Groq) reject tool_choice=none when the model still calls a tool.
		for (int round = 0; round <= maxRounds + 1; round++)
		{
			JsonObject body = new JsonObject();
			body.addProperty("model", req.getModel());
			// OpenAI's newer models reject max_tokens and require max_completion_tokens; most other servers want max_tokens.
			body.addProperty(useCompletionTokens ? "max_completion_tokens" : "max_tokens", req.getMaxTokens());
			body.add("messages", messages);
			if (toolDefs.size() > 0)
			{
				body.add("tools", toolDefs);
			}
			JsonObject res;
			try
			{
				res = HttpJson.post(http, gson, baseUrl + "/chat/completions", headers, body, host());
			}
			catch (CoachException e)
			{
				// Self-heal if the server names the other token parameter in its 400 error.
				String m = e.getMessage() == null ? "" : e.getMessage();
				if (!switchedTokenParam && e.getKind() == CoachException.Kind.BAD_CONFIG && m.contains(useCompletionTokens ? "max_tokens" : "max_completion_tokens"))
				{
					switchedTokenParam = true;
					useCompletionTokens = !useCompletionTokens;
					round--;
					continue;
				}
				throw e;
			}
			JsonObject message;
			String finish;
			try
			{
				JsonObject choice = res.getAsJsonArray("choices").get(0).getAsJsonObject();
				message = choice.getAsJsonObject("message");
				finish = choice.has("finish_reason") && !choice.get("finish_reason").isJsonNull() ? choice.get("finish_reason").getAsString() : "";
				if (message == null)
				{
					throw new NullPointerException();
				}
			}
			catch (RuntimeException e)
			{
				throw new CoachException(CoachException.Kind.INVALID_RESPONSE, host() + " response had no choices/message.", true, e);
			}

			JsonArray calls = message.has("tool_calls") && message.get("tool_calls").isJsonArray() ? message.getAsJsonArray("tool_calls") : null;
			if (calls != null && calls.size() > 0 && round <= maxRounds)
			{
				messages.add(message);
				for (JsonElement el : calls)
				{
					JsonObject call = el.getAsJsonObject();
					JsonObject fn = call.getAsJsonObject("function");
					String name = fn != null && fn.has("name") ? fn.get("name").getAsString() : "";
					JsonObject args;
					try
					{
						String raw = fn != null && fn.has("arguments") ? fn.get("arguments").getAsString() : "{}";
						args = gson.fromJson(raw, JsonObject.class);
					}
					catch (JsonSyntaxException | IllegalStateException e)
					{
						args = null;
					}
					JsonObject r = new JsonObject();
					r.addProperty("role", "tool");
					r.addProperty("tool_call_id", call.has("id") ? call.get("id").getAsString() : "");
					String result;
					if (round == maxRounds)
					{
						result = "LOOKUP_LIMIT: no more lookups are allowed for this answer. Answer now with what you have, and say what is unverified.";
					}
					else
					{
						result = args == null ? "BAD_ARGUMENTS: arguments were not valid JSON" : tools.execute(name, args);
					}
					r.addProperty("content", result);
					messages.add(r);
				}
				continue;
			}

			String out = message.has("content") && !message.get("content").isJsonNull() ? message.get("content").getAsString().trim() : "";
			if (out.isEmpty())
			{
				throw new CoachException(CoachException.Kind.INVALID_RESPONSE, host() + " returned an empty answer.", true);
			}
			if ("length".equals(finish))
			{
				out += "\n\n_(Answer cut off — raise 'Max answer length' in settings for longer replies.)_";
			}
			return new CoachReply(out, tools.sources(), tools.failures(), true, label() + " · " + req.getModel(), tools.marks());
		}
		throw new CoachException(CoachException.Kind.INVALID_RESPONSE, "The AI kept requesting lookups without answering.", true);
	}

	private static JsonObject msg(String role, String content)
	{
		JsonObject m = new JsonObject();
		m.addProperty("role", role);
		m.addProperty("content", content);
		return m;
	}
}

package com.osrscoach.ai;

/** Cleans values pasted into settings. Copy-paste often brings hidden characters that HTTP headers reject. */
public final class Secrets
{
	private Secrets()
	{
	}

	/** Keeps only visible ASCII (keys never contain anything else); drops spaces, line breaks, zero-width chars, bullets. */
	public static String cleanKey(String key)
	{
		if (key == null)
		{
			return "";
		}
		StringBuilder b = new StringBuilder(key.length());
		for (int i = 0; i < key.length(); i++)
		{
			char c = key.charAt(i);
			if (c >= 0x21 && c <= 0x7E)
			{
				b.append(c);
			}
		}
		return b.toString();
	}

	/** Removes whitespace and hidden characters anywhere in a URL, plus trailing slashes. */
	public static String cleanUrl(String url)
	{
		return cleanKey(url).replaceAll("/+$", "");
	}
}

