package com.osrscoach.research;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * General web search for anything the OSRS Wiki doesn't cover (news, Reddit threads, YouTube guides, Jagex posts).
 * Backends: Serper (Google results) or Brave Search. Blocking: call off the client and Swing threads.
 */
public class WebSearchClient
{
	public enum Backend
	{
		SERPER_GOOGLE("Google (via Serper)", "google.serper.dev"),
		BRAVE("Brave Search", "api.search.brave.com");

		public final String label;
		public final String host;

		Backend(String label, String host)
		{
			this.label = label;
			this.host = host;
		}
	}

	static final String SERPER_URL = "https://google.serper.dev/search";
	static final String BRAVE_URL = "https://api.search.brave.com/res/v1/web/search";
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final int RESULTS = 6;
	public static final int DEFAULT_PAGE_CHARS = 7000;
	private static final long MAX_PAGE_BYTES = 2_000_000;
	private static final Pattern SCRIPTS = Pattern.compile("(?is)<(script|style|noscript|svg|nav|footer|header)[^>]*>.*?</\\1>");
	private static final Pattern TAGS = Pattern.compile("(?s)<[^>]+>");
	private static final Pattern SPACE = Pattern.compile("[ \\t\\x0B\\f\\r]+");
	private static final Pattern BLANK_LINES = Pattern.compile("\\n\\s*\\n+");

	private final OkHttpClient http;
	private final Gson gson;
	private final Backend backend;
	private final String apiKey;
	private final String serperUrl;
	private final String braveUrl;

	public WebSearchClient(OkHttpClient http, Gson gson, Backend backend, String apiKey)
	{
		this(http, gson, backend, apiKey, SERPER_URL, BRAVE_URL);
	}

	WebSearchClient(OkHttpClient http, Gson gson, Backend backend, String apiKey, String serperUrl, String braveUrl)
	{
		this.http = http;
		this.gson = gson;
		this.backend = backend;
		this.apiKey = com.osrscoach.ai.Secrets.cleanKey(apiKey);
		this.serperUrl = serperUrl;
		this.braveUrl = braveUrl;
	}

	public Backend backend()
	{
		return backend;
	}

	public LookupResult search(String query) throws LookupException
	{
		if (apiKey.isEmpty())
		{
			throw new LookupException("Web search is on but no search API key is set (" + backend.label + ")");
		}
		List<Source> sources = new ArrayList<>();
		StringBuilder sb = new StringBuilder("Web results from ").append(backend.label).append(" for \"").append(query).append("\":\n");
		if (backend == Backend.SERPER_GOOGLE)
		{
			JsonObject body = new JsonObject();
			body.addProperty("q", query);
			body.addProperty("num", RESULTS);
			Request req = new Request.Builder().url(serperUrl)
				.header("X-API-KEY", apiKey)
				.post(RequestBody.create(JSON, gson.toJson(body))).build();
			JsonObject root = json(req, backend.host);
			JsonObject box = obj(root, "answerBox");
			if (box != null)
			{
				String a = firstNonEmpty(str(box, "answer"), str(box, "snippet"));
				if (!a.isEmpty())
				{
					sb.append("Google answer box: ").append(a).append(box.has("link") ? " <" + str(box, "link") + ">" : "").append('\n');
				}
			}
			JsonArray organic = root.has("organic") && root.get("organic").isJsonArray() ? root.getAsJsonArray("organic") : null;
			if (organic == null)
			{
				throw new LookupException("Unexpected response format from " + backend.host);
			}
			for (JsonElement e : organic)
			{
				add(sb, sources, e.getAsJsonObject(), "title", "link", "snippet");
			}
		}
		else
		{
			HttpUrl url = HttpUrl.parse(braveUrl).newBuilder()
				.addQueryParameter("q", query)
				.addQueryParameter("count", String.valueOf(RESULTS))
				.build();
			Request req = new Request.Builder().url(url)
				.header("X-Subscription-Token", apiKey)
				.header("Accept", "application/json").build();
			JsonObject root = json(req, backend.host);
			JsonObject web = obj(root, "web");
			JsonArray results = web != null && web.has("results") && web.get("results").isJsonArray() ? web.getAsJsonArray("results") : null;
			if (results == null)
			{
				if (root.has("type") && "search".equals(str(root, "type")))
				{
					results = new JsonArray();
				}
				else
				{
					throw new LookupException("Unexpected response format from " + backend.host);
				}
			}
			for (JsonElement e : results)
			{
				add(sb, sources, e.getAsJsonObject(), "title", "url", "description");
			}
		}
		if (sources.isEmpty())
		{
			sb.append("(no results)\n");
		}
		return new LookupResult(sb.toString(), sources);
	}

	/** Reads one result page as plain text. Only http(s); size-capped; HTML stripped. */
	public LookupResult fetch(String url) throws LookupException
	{
		return fetch(url, DEFAULT_PAGE_CHARS);
	}

	public LookupResult fetch(String url, int maxChars) throws LookupException
	{
		HttpUrl u = HttpUrl.parse(url);
		if (u == null)
		{
			throw new LookupException("Not a valid web address");
		}
		Request req = new Request.Builder().url(u)
			.header("User-Agent", WikiClient.USER_AGENT)
			.header("Accept", "text/html,text/plain;q=0.9,*/*;q=0.5").build();
		try (Response res = http.newCall(req).execute())
		{
			ResponseBody body = res.body();
			if (!res.isSuccessful() || body == null)
			{
				throw new LookupException("Page fetch failed: HTTP " + res.code() + " from " + u.host());
			}
			MediaType type = body.contentType();
			if (type != null && !"text".equals(type.type()) && !type.subtype().contains("html") && !type.subtype().contains("json"))
			{
				throw new LookupException("That page isn't text (" + type + ")");
			}
			okio.BufferedSource src = body.source();
			src.request(MAX_PAGE_BYTES);
			okio.Buffer buf = src.getBuffer();
			String raw = buf.readUtf8(Math.min(buf.size(), MAX_PAGE_BYTES));
			String text = htmlToText(raw);
			boolean cut = text.length() > maxChars;
			if (cut)
			{
				text = text.substring(0, maxChars);
			}
			String title = u.host();
			return new LookupResult("Page: " + url + "\n" + text + (cut ? "\n[...page truncated...]" : ""),
				java.util.Collections.singletonList(new Source(title, url, null)));
		}
		catch (IOException e)
		{
			throw new LookupException("Couldn't reach " + u.host() + " (" + e.getClass().getSimpleName() + ")", e);
		}
	}

	static String htmlToText(String html)
	{
		String s = SCRIPTS.matcher(html).replaceAll(" ");
		s = s.replaceAll("(?i)<(br|/p|/div|/li|/h[1-6]|/tr)[^>]*>", "\n");
		s = TAGS.matcher(s).replaceAll(" ");
		s = s.replace("&nbsp;", " ").replace("&amp;", "&").replace("&quot;", "\"").replace("&#39;", "'").replace("&#039;", "'").replace("&lt;", "<").replace("&gt;", ">");
		s = SPACE.matcher(s).replaceAll(" ");
		s = BLANK_LINES.matcher(s).replaceAll("\n");
		return s.trim();
	}

	private JsonObject json(Request req, String host) throws LookupException
	{
		try (Response res = http.newCall(req).execute())
		{
			ResponseBody body = res.body();
			if (res.code() == 401 || res.code() == 403)
			{
				throw new LookupException("Search key rejected by " + host + " (HTTP " + res.code() + ")");
			}
			if (res.code() == 429 || res.code() == 402)
			{
				throw new LookupException("Search quota used up or rate limited at " + host + " (HTTP " + res.code() + ")");
			}
			if (!res.isSuccessful() || body == null)
			{
				throw new LookupException("Search failed: HTTP " + res.code() + " from " + host);
			}
			JsonElement el = gson.fromJson(body.charStream(), JsonElement.class);
			if (el == null || !el.isJsonObject())
			{
				throw new LookupException("Unexpected response format from " + host);
			}
			return el.getAsJsonObject();
		}
		catch (IOException e)
		{
			throw new LookupException("Couldn't reach " + host + " (" + e.getClass().getSimpleName() + ")", e);
		}
		catch (RuntimeException e)
		{
			throw new LookupException("Unreadable response from " + host, e);
		}
	}

	private static void add(StringBuilder sb, List<Source> sources, JsonObject o, String titleKey, String urlKey, String snippetKey)
	{
		String title = str(o, titleKey);
		String link = str(o, urlKey);
		if (link.isEmpty() || !(link.startsWith("https://") || link.startsWith("http://")))
		{
			return;
		}
		String snippet = TAGS.matcher(str(o, snippetKey)).replaceAll("");
		sb.append("- ").append(title).append(" <").append(link).append(">: ").append(snippet).append('\n');
		sources.add(new Source(title.isEmpty() ? link : title, link, null));
	}

	private static JsonObject obj(JsonObject o, String k)
	{
		return o.has(k) && o.get(k).isJsonObject() ? o.getAsJsonObject(k) : null;
	}

	private static String str(JsonObject o, String k)
	{
		return o.has(k) && o.get(k).isJsonPrimitive() ? o.get(k).getAsString() : "";
	}

	private static String firstNonEmpty(String a, String b)
	{
		return a.isEmpty() ? b : a;
	}
}

package com.osrscoach.research;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.URLEncoder;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Read-only access to the OSRS Wiki (MediaWiki API) and the wiki's real-time price API.
 * All methods block and MUST be called off the client and Swing threads.
 *
 * The wiki asks API users to send a descriptive User-Agent:
 * https://oldschool.runescape.wiki/w/RuneScape:Real-time_Prices#Please_set_a_descriptive_User-Agent!
 */
public class WikiClient
{
	public static final String WIKI = "https://oldschool.runescape.wiki";
	public static final String PRICES = "https://prices.runescape.wiki/api/v1/osrs";
	static final String USER_AGENT = "osrs-coach RuneLite plugin (beginner coach; github.com/runelite/plugin-hub)";
	public static final int DEFAULT_PAGE_CHARS = 9000;
	private static final long MAPPING_TTL_MS = 6L * 3600 * 1000;
	private static final Pattern TAGS = Pattern.compile("<[^>]+>");
	private static final DateTimeFormatter HHMM = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm 'UTC'").withZone(ZoneOffset.UTC);

	private final OkHttpClient http;
	private final Gson gson;
	private final Clock clock;
	private final String wikiBase;
	private final String pricesBase;

	private Map<String, int[]> nameToId; // lowercased name -> {id}
	private long mappingLoadedAt;

	public WikiClient(OkHttpClient http, Gson gson)
	{
		this(http, gson, Clock.systemUTC(), WIKI, PRICES);
	}

	public WikiClient(OkHttpClient http, Gson gson, Clock clock, String wikiBase, String pricesBase)
	{
		this.http = http;
		this.gson = gson;
		this.clock = clock;
		this.wikiBase = wikiBase;
		this.pricesBase = pricesBase;
	}

	public LookupResult search(String query) throws LookupException
	{
		HttpUrl url = HttpUrl.parse(wikiBase + "/api.php").newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("list", "search")
			.addQueryParameter("srsearch", query)
			.addQueryParameter("srlimit", "5")
			.addQueryParameter("format", "json")
			.build();
		JsonObject root = getJson(url).getAsJsonObject();
		JsonArray hits = path(root, "query", "search");
		if (hits == null)
		{
			throw new LookupException("Wiki search returned an unexpected format");
		}
		StringBuilder sb = new StringBuilder();
		List<Source> sources = new ArrayList<>();
		for (JsonElement e : hits)
		{
			JsonObject h = e.getAsJsonObject();
			String title = h.get("title").getAsString();
			String snippet = h.has("snippet") ? unescape(TAGS.matcher(h.get("snippet").getAsString()).replaceAll("")) : "";
			String link = pageUrl(title);
			sb.append("- ").append(title).append(" <").append(link).append(">: ").append(snippet).append('\n');
			sources.add(new Source(title, link, null));
		}
		if (sources.isEmpty())
		{
			return new LookupResult("No OSRS Wiki pages matched \"" + query + "\".", Collections.emptyList());
		}
		return new LookupResult(sb.toString(), sources);
	}

	public LookupResult page(String title) throws LookupException
	{
		return page(title, DEFAULT_PAGE_CHARS);
	}

	public LookupResult page(String title, int maxChars) throws LookupException
	{
		HttpUrl url = HttpUrl.parse(wikiBase + "/api.php").newBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", title)
			.addQueryParameter("prop", "wikitext")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();
		JsonObject root = getJson(url).getAsJsonObject();
		if (root.has("error"))
		{
			String info = root.getAsJsonObject("error").has("info") ? root.getAsJsonObject("error").get("info").getAsString() : "unknown";
			return new LookupResult("Wiki page \"" + title + "\" not found (" + info + "). Try wiki_search first.", Collections.emptyList());
		}
		JsonObject parse = root.getAsJsonObject("parse");
		if (parse == null || !parse.has("wikitext"))
		{
			throw new LookupException("Wiki page response had no content");
		}
		String realTitle = parse.get("title").getAsString();
		String text = cleanWikitext(parse.get("wikitext").getAsString());
		boolean truncated = text.length() > maxChars;
		if (truncated)
		{
			text = text.substring(0, maxChars);
		}
		String link = pageUrl(realTitle);
		return new LookupResult("Page: " + realTitle + " <" + link + ">\n" + text + (truncated ? "\n[...page truncated...]" : ""),
			Collections.singletonList(new Source(realTitle, link, null)));
	}

	private static final Pattern[] NOISE = {
		Pattern.compile("(?s)<!--.*?-->"),
		Pattern.compile("(?s)<ref[^>/]*>.*?</ref>"),
		Pattern.compile("<ref[^>]*/>"),
		Pattern.compile("(?s)<gallery[^>]*>.*?</gallery>"),
		Pattern.compile("(?s)<poem>.*?</poem>"),
		Pattern.compile("\\[\\[(?:File|Image):[^\\[\\]]*(?:\\[\\[[^\\]]*\\]\\][^\\[\\]]*)*\\]\\]"),
		Pattern.compile("\\{\\{(?:External|Has quick guide|Otheruses|Redirect|Relativeloc|Has calculator|Members|Free-to-play)[^{}]*\\}\\}"),
		Pattern.compile("(?m)^\\|\\s*(?:image|update|release|developer|leagueRegion|series|number|aka)\\s*=.*$"),
		Pattern.compile("(?m)^\\[\\[Category:.*$"),
	};
	private static final Pattern PIPED_LINK = Pattern.compile("\\[\\[[^\\[\\]|]*\\|([^\\[\\]]*)\\]\\]");
	private static final Pattern PLAIN_LINK = Pattern.compile("\\[\\[([^\\[\\]|]*)\\]\\]");
	private static final Pattern MANY_BLANK = Pattern.compile("\\n{3,}");

	/** Drops references, images, comments and housekeeping lines; keeps text, templates and map coordinates. */
	static String cleanWikitext(String t)
	{
		String s = t;
		for (Pattern p : NOISE)
		{
			s = p.matcher(s).replaceAll("");
		}
		s = PIPED_LINK.matcher(s).replaceAll("$1");
		s = PLAIN_LINK.matcher(s).replaceAll("$1");
		s = s.replace("'''", "").replace("''", "");
		s = MANY_BLANK.matcher(s).replaceAll("\n\n");
		return s.trim();
	}

	public LookupResult price(String itemName) throws LookupException
	{
		Integer id = findItemId(itemName);
		if (id == null)
		{
			return new LookupResult("No tradeable item named \"" + itemName + "\" in the price list. Check the exact in-game name.", Collections.emptyList());
		}
		HttpUrl url = HttpUrl.parse(pricesBase + "/latest").newBuilder().addQueryParameter("id", String.valueOf(id)).build();
		JsonObject root = getJson(url).getAsJsonObject();
		JsonObject data = root.getAsJsonObject("data");
		JsonObject p = data == null ? null : data.getAsJsonObject(String.valueOf(id));
		Instant checked = clock.instant();
		String link = "https://prices.runescape.wiki/osrs/item/" + id;
		if (p == null)
		{
			return new LookupResult("No recent trades recorded for " + itemName + " (id " + id + ").",
				Collections.singletonList(new Source(itemName + " price", link, "checked " + HHMM.format(checked))));
		}
		StringBuilder sb = new StringBuilder();
		sb.append(itemName).append(" (id ").append(id).append(") Grand Exchange real-time price, checked ").append(HHMM.format(checked)).append(":\n");
		appendPrice(sb, "Instant-buy (high)", p, "high", "highTime");
		appendPrice(sb, "Instant-sell (low)", p, "low", "lowTime");
		sb.append("Source: ").append(link).append('\n');
		return new LookupResult(sb.toString(), Collections.singletonList(new Source(itemName + " price", link, "checked " + HHMM.format(checked))));
	}

	private void appendPrice(StringBuilder sb, String label, JsonObject p, String key, String timeKey)
	{
		sb.append(label).append(": ");
		if (p.has(key) && !p.get(key).isJsonNull())
		{
			sb.append(String.format(Locale.ROOT, "%,d gp", p.get(key).getAsLong()));
			if (p.has(timeKey) && !p.get(timeKey).isJsonNull())
			{
				sb.append(" (last trade ").append(HHMM.format(Instant.ofEpochSecond(p.get(timeKey).getAsLong()))).append(')');
			}
		}
		else
		{
			sb.append("no data");
		}
		sb.append('\n');
	}

	synchronized Integer findItemId(String name) throws LookupException
	{
		long now = clock.millis();
		if (nameToId == null || now - mappingLoadedAt > MAPPING_TTL_MS)
		{
			JsonElement el = getJson(HttpUrl.parse(pricesBase + "/mapping"));
			if (!el.isJsonArray())
			{
				throw new LookupException("Price mapping had an unexpected format");
			}
			Map<String, int[]> m = new HashMap<>();
			for (JsonElement e : el.getAsJsonArray())
			{
				JsonObject o = e.getAsJsonObject();
				m.put(o.get("name").getAsString().toLowerCase(Locale.ROOT), new int[]{o.get("id").getAsInt()});
			}
			nameToId = m;
			mappingLoadedAt = now;
		}
		int[] id = nameToId.get(name.trim().toLowerCase(Locale.ROOT));
		return id == null ? null : id[0];
	}

	public String pageUrl(String title)
	{
		try
		{
			return wikiBase + "/w/" + URLEncoder.encode(title.replace(' ', '_'), "UTF-8").replace("%2F", "/").replace("%3A", ":").replace("%27", "'");
		}
		catch (java.io.UnsupportedEncodingException e)
		{
			throw new IllegalStateException(e);
		}
	}

	private JsonElement getJson(HttpUrl url) throws LookupException
	{
		Request req = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
		try (Response res = http.newCall(req).execute())
		{
			ResponseBody body = res.body();
			if (!res.isSuccessful() || body == null)
			{
				throw new LookupException("Lookup failed: HTTP " + res.code() + " from " + url.host());
			}
			JsonElement el = gson.fromJson(body.charStream(), JsonElement.class);
			if (el == null)
			{
				throw new LookupException("Empty response from " + url.host());
			}
			return el;
		}
		catch (IOException e)
		{
			throw new LookupException("Couldn't reach " + url.host() + " (" + e.getClass().getSimpleName() + ")", e);
		}
		catch (RuntimeException e)
		{
			throw new LookupException("Unreadable response from " + url.host(), e);
		}
	}

	private static JsonArray path(JsonObject o, String a, String b)
	{
		if (o == null || !o.has(a) || !o.get(a).isJsonObject())
		{
			return null;
		}
		JsonObject x = o.getAsJsonObject(a);
		return x.has(b) && x.get(b).isJsonArray() ? x.getAsJsonArray(b) : null;
	}

	private static String unescape(String s)
	{
		return s.replace("&quot;", "\"").replace("&#039;", "'").replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">");
	}

}

