	{
		JPopupMenu menu = new JPopupMenu();
		for (String s : skillNames)
		{
			JMenuItem item = new JMenuItem(s);
			item.addActionListener(e -> ask("What is the best way to train " + s + " at my level? Keep it beginner-friendly."));
			menu.add(item);
