	private void addBubble(String html, Color bg, String footer, boolean user)
	{
		JEditorPane pane = new JEditorPane();
		pane.setEditorKit(new HTMLEditorKit());
		pane.setEditable(false);
		pane.setOpaque(true);
		pane.setBackground(bg);
		pane.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES, Boolean.TRUE);
		pane.setFont(chatFont());
		pane.setForeground(user ? Color.WHITE : ColorScheme.TEXT_COLOR);
		pane.setBorder(new EmptyBorder(6, 8, 6, 8));
		pane.setText("<html><body style='margin:0'>" + (user ? "<span style='color:#9a9a9a'>You</span><br>" : "") + html + "</body></html>");
		pane.addHyperlinkListener(e ->
		{
			if (e.getEventType() == HyperlinkEvent.EventType.ACTIVATED && e.getURL() != null)
			{
				String u = e.getURL().toString();
				if (u.startsWith("https://") || u.startsWith("http://"))
				{
					LinkBrowser.browse(u);
				}
			}
		});
		row.gridy++;
		chat.add(pane, row.clone());
		JLabel foot = new JLabel(footer == null ? "" : footer);
		foot.setFont(FontManager.getRunescapeSmallFont());
		foot.setForeground(footer != null && footer.startsWith("MOCK") ? MOCK_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);
		row.gridy++;
		chat.add(foot, row.clone());
		chat.revalidate();
		chat.repaint();
		SwingUtilities.invokeLater(() -> chatScroll.getVerticalScrollBar().setValue(chatScroll.getVerticalScrollBar().getMaximum()));
	}

	private java.awt.Font chatFont()
	{
		return FontManager.getRunescapeSmallFont().deriveFont((float) config.get().textSize().points);
	}

	/** Any thread. Re-applies the chat text size to existing and future messages. */
	public void applyTextSize()
	{
		SwingUtilities.invokeLater(() ->
		{
			java.awt.Font f = chatFont();
			for (Component comp : chat.getComponents())
			{
				if (comp instanceof JEditorPane)
				{
					comp.setFont(f);
				}
			}
			input.setFont(f);
			chat.revalidate();
			chat.repaint();
		});
	}

	private void setBusy(boolean b)
	{
		busy = b;
		send.setEnabled(!b);
		send.setText(b ? "…" : "Ask");
		for (Component c : quick.getComponents())
		{
			c.setEnabled(!b);
		}
	}

	private static JButton small(String text, String tip, Runnable r)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setMargin(new Insets(2, 2, 2, 2));
		b.setFocusPainted(false);
		if (tip != null)
		{
			b.setToolTipText(tip);
		}
		b.addActionListener(e -> r.run());
		return b;
	}

	private static <T extends javax.swing.JComponent> T left(T c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		return c;
	}

	private static String wrap(String html)
	{
		return "<html><body style='width:" + (PANEL_WIDTH - 30) + "px'>" + html + "</body></html>";
	}
}

package com.osrscoach.ui;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Minimal, safe Markdown → HTML for chat bubbles. Escapes everything first, so model output can't inject markup. */
public final class Markdown
{
	private static final Pattern LINK = Pattern.compile("\\[([^\\]]{1,200})\\]\\((https?://[^\\s)]{1,500})\\)");
	private static final Pattern BARE_URL = Pattern.compile("(?<![\"=>])(https?://[^\\s<)\\]]{1,500})");
	private static final Pattern BOLD = Pattern.compile("\\*\\*(.+?)\\*\\*");
	private static final Pattern ITALIC = Pattern.compile("(?<![\\w*])_(.+?)_(?![\\w*])");
	private static final Pattern CODE = Pattern.compile("`([^`]{1,200})`");
	private static final Pattern HEADING = Pattern.compile("(?m)^#{1,6}\\s*(.+)$");
	private static final Pattern BULLET = Pattern.compile("(?m)^\\s*[-*]\\s+");

	private Markdown()
	{
	}

	public static String toHtml(String md)
	{
		if (md == null)
		{
			return "";
		}
		String s = escape(md.replace("\r", ""));
		s = HEADING.matcher(s).replaceAll("<b>$1</b>");
		s = BULLET.matcher(s).replaceAll("• ");
		// Links: convert [text](url) first, protecting them from the bare-URL pass with a placeholder.
		StringBuffer out = new StringBuffer();
		Matcher m = LINK.matcher(s);
		while (m.find())
		{
			m.appendReplacement(out, Matcher.quoteReplacement("<a href=\"" + m.group(2) + "\">" + m.group(1) + "</a>"));
		}
		m.appendTail(out);
		s = out.toString();
		out = new StringBuffer();
		m = BARE_URL.matcher(s);
		while (m.find())
		{
			String url = m.group(1);
			m.appendReplacement(out, Matcher.quoteReplacement("<a href=\"" + url + "\">" + shorten(url) + "</a>"));
		}
		m.appendTail(out);
		s = out.toString();
		s = BOLD.matcher(s).replaceAll("<b>$1</b>");
		s = ITALIC.matcher(s).replaceAll("<i>$1</i>");
		s = CODE.matcher(s).replaceAll("<tt>$1</tt>");
		return s.replace("\n", "<br>");
	}

	public static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
	}

	static String shorten(String url)
	{
		String u = url.replaceFirst("^https?://(www\\.)?", "");
		return u.length() > 42 ? u.substring(0, 40) + "…" : u;
	}
}

