class BackupProviderTest
{
	private static final Gson GSON = new Gson();
	private final ScheduledExecutorService exec = Executors.newSingleThreadScheduledExecutor();

	@AfterEach
	void stop()
	{
		exec.shutdownNow();
	}

	private static CoachConfig cfg(boolean withBackup)
	{
		return new CoachConfig()
		{
			@Override public Provider provider() { return Provider.OPENAI_COMPATIBLE; }
			@Override public String apiKey() { return "hf"; }
			@Override public String model() { return "openai/gpt-oss-120b"; }
			@Override public String baseUrl() { return "https://router.huggingface.co/v1"; }
			@Override public boolean wikiLookups() { return false; }
			@Override public String backup1BaseUrl() { return withBackup ? "https://generativelanguage.googleapis.com/v1beta/openai/" : ""; }
			@Override public String backup1ApiKey() { return "AIza"; }
			@Override public String backup1Model() { return "gemini-3.8-flash"; }
		};
	}

	private CoachService service(FakeHttp ai, boolean backup)
	{
		WikiClient w = new WikiClient(new FakeHttp().client(), GSON, Clock.fixed(MockData.NOW, ZoneOffset.UTC), WikiClient.WIKI, WikiClient.PRICES);
		CoachService s = new CoachService(() -> CompletableFuture.completedFuture(MockData.beginner()), () -> cfg(backup), () -> null,
			ai.client(), GSON, w, exec, Clock.fixed(MockData.NOW, ZoneOffset.UTC));
		s.retryUnit = TimeUnit.MILLISECONDS;
		return s;
	}

	@Test
	void outOfCreditFallsBackToBackup() throws Exception
	{
		FakeHttp ai = new FakeHttp()
			.respond(402, "{\"error\":\"You have no remaining credits.\"}")
			.respond(200, "{\"choices\":[{\"message\":{\"content\":\"from gemini\"}}]}");
		List<String> progress = new CopyOnWriteArrayList<>();
		CoachReply r = service(ai, true).ask("q", progress::add).get(5, TimeUnit.SECONDS);
		assertEquals("from gemini", r.getText());
		assertTrue(ai.requests.get(0).url().host().equals("router.huggingface.co"));
		assertTrue(ai.requests.get(1).url().toString().startsWith("https://generativelanguage.googleapis.com/v1beta/openai/chat/completions"));
		assertEquals("Bearer AIza", ai.requests.get(1).header("Authorization"));
		assertTrue(ai.bodies.get(1).contains("gemini-3.8-flash"));
		assertTrue(r.getWarnings().get(0).contains("answered by Backup 1 (generativelanguage.googleapis.com)"), r.getWarnings().toString());
		assertTrue(progress.get(0).contains("trying Backup 1"), progress.toString());
	}

	@Test
	void allFailingSurfacesLastError()
	{
		FakeHttp ai = new FakeHttp()
			.respond(402, "{\"error\":\"no credit\"}")
			.respond(401, "{\"error\":{\"message\":\"bad key\"}}");
		ExecutionException e = assertThrows(ExecutionException.class, () -> service(ai, true).ask("q", null).get(5, TimeUnit.SECONDS));
		assertEquals(CoachException.Kind.AUTH, ((CoachException) e.getCause()).getKind());
		String msg = e.getCause().getMessage();
		assertTrue(msg.startsWith("All AI services failed."), msg);
		assertTrue(msg.contains("Main provider (router.huggingface.co)") && msg.contains("out of credit"), msg);
		assertTrue(msg.contains("Backup 1 (generativelanguage.googleapis.com)") && msg.contains("bad key"), msg);
	}

	@Test
	void noBackupConfiguredMeansSingleAttempt()
	{
		FakeHttp ai = new FakeHttp().respond(402, "{\"error\":\"no credit\"}");
		assertThrows(ExecutionException.class, () -> service(ai, false).ask("q", null).get(5, TimeUnit.SECONDS));
		assertEquals(1, ai.requests.size());
	}

	@Test
	void hostOf()
	{
		assertEquals("api.groq.com", CoachService.hostOf("https://api.groq.com/openai/v1"));
		assertEquals("localhost:1234", CoachService.hostOf("http://localhost:1234/v1"));
	}

	@Test
	void shortWaitOnMainIsRetriedEvenIfBackupsFailWithoutHint() throws Exception
	{
		FakeHttp ai = new FakeHttp()
			.respond(429, "{\"error\":{\"message\":\"Rate limit reached. Please try again in 3.4125s.\"}}")
			.respond(429, "{\"error\":{\"message\":\"You exceeded your current quota\"}}")
			.respond(200, "{\"choices\":[{\"message\":{\"content\":\"main again\"}}]}");
		List<String> progress = new CopyOnWriteArrayList<>();
		CoachReply r = service(ai, true).ask("q", progress::add).get(5, TimeUnit.SECONDS);
		assertEquals("main again", r.getText());
		assertEquals("router.huggingface.co", ai.requests.get(2).url().host());
		assertTrue(progress.stream().anyMatch(p -> p.contains("waiting 4s")), progress.toString());
	}
}

package com.osrscoach.ai;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.osrscoach.CoachConfig;
import com.osrscoach.FakeHttp;
import com.osrscoach.MockData;
import com.osrscoach.context.AccountSnapshot;
import com.osrscoach.context.Availability;
import com.osrscoach.research.WikiClient;
import java.time.Clock;
import java.time.ZoneOffset;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Supplier;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class CoachServiceTest
{
	private final ScheduledExecutorService exec = Executors.newSingleThreadScheduledExecutor();
	private static final Gson GSON = new Gson();

	@AfterEach
	void stop()
	{
		exec.shutdownNow();
	}

	private CoachService service(CoachConfig cfg, Supplier<CompletableFuture<AccountSnapshot>> snap, FakeHttp ai, FakeHttp wiki)
	{
		WikiClient w = new WikiClient(wiki.client(), GSON, Clock.fixed(MockData.NOW, ZoneOffset.UTC), WikiClient.WIKI, WikiClient.PRICES);
		return new CoachService(snap, () -> cfg, () -> null, ai.client(), GSON, w, exec, Clock.fixed(MockData.NOW, ZoneOffset.UTC));
	}

	@Test
	void mockModeIsLabelledAndUsesAccountData() throws Exception
	{
		FakeHttp wiki = new FakeHttp().respond(200, "{\"query\":{\"search\":[{\"title\":\"Sheep Shearer\",\"snippet\":\"\"}]}}");
		CoachService s = service(MockData.config(CoachConfig.Provider.MOCK, "", true), () -> CompletableFuture.completedFuture(MockData.beginner()), new FakeHttp(), wiki);
		CoachReply r = s.ask("anything").get();
		assertFalse(r.isLive());
		assertTrue(r.getText().startsWith(MockProvider.BANNER));
		assertTrue(r.getText().contains("Continue **Sheep Shearer**"));
		assertEquals(1, r.getLookedUp().size(), "mock still demonstrates a real wiki lookup");
	}

	@Test
	void mockModeWithSearchUnavailable() throws Exception
	{
		CoachService s = service(MockData.config(CoachConfig.Provider.MOCK, "", true), () -> CompletableFuture.completedFuture(MockData.beginner()),
			new FakeHttp(), new FakeHttp().fail(new java.net.UnknownHostException("wiki")));
		CoachReply r = s.ask("x").get();
		assertTrue(r.getText().contains("Wiki lookup failed"));
		assertEquals(1, r.getWarnings().size());
	}

	@Test
	void mockModeLoggedOut() throws Exception
	{
		CoachService s = service(MockData.config(CoachConfig.Provider.MOCK, "", false), () -> CompletableFuture.completedFuture(AccountSnapshot.loggedOut(MockData.NOW)), new FakeHttp(), new FakeHttp());
		assertTrue(s.ask("x").get().getText().contains("Log in"));
	}

	@Test
	void contextReadFailureIsMarkedUnavailableNotZero() throws Exception
	{
		FakeHttp ai = new FakeHttp().respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"ok\"}]}");
		CompletableFuture<AccountSnapshot> broken = new CompletableFuture<>();
		broken.completeExceptionally(new IllegalStateException("client thread died"));
		CoachService s = service(MockData.config(CoachConfig.Provider.ANTHROPIC, "k", false), () -> broken, ai, new FakeHttp());
		s.ask("x").get();
		assertEquals(Availability.ERROR, s.lastSnapshot().getSkillsAvailability());
		String system = GSON.fromJson(ai.bodies.get(0), JsonObject.class).get("system").getAsString();
		assertTrue(system.contains("unavailable: read error — do NOT treat skills as level 1"), system);
		assertTrue(system.contains("Lookup tools: UNAVAILABLE"));
	}

	@Test
	void liveRequestCarriesCoreInstructionContextAndHistory() throws Exception
	{
		FakeHttp ai = new FakeHttp()
			.respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"first\"}]}")
			.respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"second\"}]}");
		CoachService s = service(MockData.config(CoachConfig.Provider.ANTHROPIC, "k", true), () -> CompletableFuture.completedFuture(MockData.beginner()), ai, new FakeHttp());
		s.ask("q1").get();
		s.ask("q2").get();
		JsonObject body = GSON.fromJson(ai.bodies.get(1), JsonObject.class);
		String system = body.get("system").getAsString();
		assertTrue(system.startsWith(CoachPrompt.CORE));
		assertTrue(system.contains("Budget: 200k gp"));
		assertTrue(system.contains("Sheep Shearer"));
		assertEquals(3, body.getAsJsonArray("messages").size(), "q1, first, q2");
		s.clearHistory();
	}

	@Test
	void errorsSurfaceAsCoachException()
	{
		CoachService s = service(MockData.config(CoachConfig.Provider.ANTHROPIC, "", true), () -> CompletableFuture.completedFuture(MockData.beginner()), new FakeHttp(), new FakeHttp());
		ExecutionException e = org.junit.jupiter.api.Assertions.assertThrows(ExecutionException.class, () -> s.ask("x").get());
		assertTrue(e.getCause() instanceof CoachException);
		assertEquals(CoachException.Kind.NO_CREDENTIALS, ((CoachException) e.getCause()).getKind());
	}

	@Test
	void webSearchToolsOfferedOnlyWhenConfigured() throws Exception
	{
		FakeHttp ai = new FakeHttp()
			.respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"a\"}]}")
			.respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"b\"}]}");
		CoachConfig off = MockData.config(CoachConfig.Provider.ANTHROPIC, "k", true);
		CoachConfig on = new CoachConfig()
		{
			@Override public Provider provider() { return Provider.ANTHROPIC; }
			@Override public String apiKey() { return "k"; }
			@Override public WebSearch webSearch() { return WebSearch.SERPER_GOOGLE; }
			@Override public String webSearchKey() { return "s"; }
		};
		service(off, () -> CompletableFuture.completedFuture(MockData.beginner()), ai, new FakeHttp()).ask("q").get();
		service(on, () -> CompletableFuture.completedFuture(MockData.beginner()), ai, new FakeHttp()).ask("q").get();
		assertFalse(ai.bodies.get(0).contains("web_search"));
		assertTrue(ai.bodies.get(0).contains("General web search is OFF"));
		assertTrue(ai.bodies.get(1).contains("\"name\":\"web_search\""));
		assertTrue(ai.bodies.get(1).contains("Source priority: OSRS Wiki"));
	}
}

package com.osrscoach.ai;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.osrscoach.FakeHttp;
import com.osrscoach.MockData;
import com.osrscoach.research.WikiClient;
import java.time.Clock;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class MarkLocationTest
{
	private final List<String> placed = new ArrayList<>();
	private final MapMarker fake = new MapMarker()
	{
		@Override
		public void mark(String label, int x, int y, int plane)
		{
			placed.add(label + "@" + x + "," + y + "," + plane);
		}

		@Override
		public void clear()
		{
			placed.clear();
		}
	};

	private CoachTools tools(FakeHttp wiki)
	{
		return new CoachTools(new WikiClient(wiki.client(), new Gson(), Clock.fixed(MockData.NOW, ZoneOffset.UTC), WikiClient.WIKI, WikiClient.PRICES)).withMarker(fake);
	}

	private static JsonObject mark(String label, int x, int y)
	{
		JsonObject o = new JsonObject();
		o.addProperty("label", label);
		o.addProperty("x", x);
		o.addProperty("y", y);
		return o;
	}

	private static JsonObject page(String title)
	{
		JsonObject o = new JsonObject();
		o.addProperty("title", title);
		return o;
	}

	@Test
	void guessedCoordinatesAreRejected()
	{
		CoachTools t = tools(new FakeHttp());
		assertTrue(t.execute("mark_location", mark("Ghouls", 3423, 3461)).startsWith("COORDINATES_UNVERIFIED"));
		assertTrue(placed.isEmpty());
	}

	@Test
	void coordinatesFromFetchedWikiPageAreMarked()
	{
		FakeHttp wiki = new FakeHttp().respond(200, "{\"parse\":{\"title\":\"Ghoul\",\"wikitext\":\"{{Map|x:3423,y:3461|x:3426,y:3465}}\"}}");
		CoachTools t = tools(wiki);
		t.execute("wiki_page", page("Ghoul"));
		String out = t.execute("mark_location", mark("Ghouls north of Canifis", 3423, 3461));
		assertTrue(out.startsWith("MARKED"), out);
		assertEquals("Ghouls north of Canifis@3423,3461,0", placed.get(0));
		assertEquals(1, t.marks().size());
	}

	@Test
	void startmapFormatAccepted()
	{
		FakeHttp wiki = new FakeHttp().respond(200, "{\"parse\":{\"title\":\"Priest in Peril\",\"wikitext\":\"|startmap = 3221,3473\"}}");
		CoachTools t = tools(wiki);
		t.execute("wiki_page", page("Priest in Peril"));
		assertTrue(t.execute("mark_location", mark("Drezel", 3221, 3473)).startsWith("MARKED"));
		assertTrue(t.execute("mark_location", mark("Nearby guess", 3222, 3473)).startsWith("COORDINATES_UNVERIFIED"));
	}

	@Test
	void outOfWorldAndBadArgsRejected()
	{
		CoachTools t = tools(new FakeHttp());
		assertTrue(t.execute("mark_location", mark("Nowhere", 99999, 5)).startsWith("COORDINATES_REJECTED"));
		JsonObject bad = new JsonObject();
		bad.addProperty("label", "x");
		assertTrue(t.execute("mark_location", bad).startsWith("BAD_ARGUMENTS"));
	}

	@Test
	void toolOnlyOfferedWithWikiAndMarker()
	{
		assertTrue(tools(new FakeHttp()).specs().stream().anyMatch(s -> s.name.equals("mark_location")));
		assertFalse(new CoachTools(null).withMarker(fake).specs().stream().anyMatch(s -> s.name.equals("mark_location")));
		assertTrue(new CoachTools(null).withMarker(fake).execute("mark_location", mark("a", 3200, 3200)).startsWith("MARKER_UNAVAILABLE"));
	}

	@Test
	void seenInTextPatterns()
	{
		assertTrue(CoachTools.seenInFetchedText("x:3209,y:3214|r=3", 3209, 3214));
		assertTrue(CoachTools.seenInFetchedText("{{map|3410,3494|zoom=3}}", 3410, 3494));
		assertFalse(CoachTools.seenInFetchedText("13410,3494", 3410, 3494));
		assertFalse(CoachTools.seenInFetchedText("3410,34945", 3410, 3494));
	}
}

package com.osrscoach.ai;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.osrscoach.FakeHttp;
import com.osrscoach.MockData;
import com.osrscoach.research.WikiClient;
import java.net.SocketTimeoutException;
import java.net.UnknownHostException;
import java.time.Clock;
import java.time.ZoneOffset;
import java.util.Collections;
import org.junit.jupiter.api.Test;

class ProvidersTest
{
	private static final Gson GSON = new Gson();
	private static final String KEY = "sk-ant-TEST-SECRET-123";

	private static CoachRequest req()
	{
		return CoachRequest.builder().systemPrompt("sys").history(Collections.singletonList(new ChatTurn(ChatTurn.Role.USER, "earlier")))
			.userMessage("What next?").model("claude-sonnet-5-5").maxTokens(500).accountContext("ctx").build();
	}

	private static CoachTools tools(FakeHttp f)
	{
		return new CoachTools(new WikiClient(f.client(), GSON, Clock.fixed(MockData.NOW, ZoneOffset.UTC), WikiClient.WIKI, WikiClient.PRICES));
	}

	// ---------------- Anthropic ----------------

	@Test
	void anthropicToolLoopFetchesWikiAndReturnsSources() throws Exception
	{
		FakeHttp ai = new FakeHttp()
			.respond(200, "{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"text\",\"text\":\"Let me check.\"},{\"type\":\"tool_use\",\"id\":\"tu_1\",\"name\":\"wiki_search\",\"input\":{\"query\":\"Sheep Shearer\"}}]}")
			.respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"**Next step:** Finish Sheep Shearer.\"}]}");
		FakeHttp wiki = new FakeHttp().respond(200, "{\"query\":{\"search\":[{\"title\":\"Sheep Shearer\",\"snippet\":\"wool\"}]}}");

		CoachReply r = new AnthropicProvider(ai.client(), GSON, KEY).respond(req(), tools(wiki));

		assertEquals("**Next step:** Finish Sheep Shearer.", r.getText());
		assertTrue(r.isLive());
		assertEquals("https://oldschool.runescape.wiki/w/Sheep_Shearer", r.getLookedUp().get(0).getUrl());
		assertEquals(KEY, ai.requests.get(0).header("x-api-key"));
		assertEquals("2023-06-01", ai.requests.get(0).header("anthropic-version"));
		JsonObject second = GSON.fromJson(ai.bodies.get(1), JsonObject.class);
		String secondMsgs = second.get("messages").toString();
		assertTrue(secondMsgs.contains("tool_result") && secondMsgs.contains("tu_1"), secondMsgs);
		assertTrue(secondMsgs.contains("reference_material"), "tool output must be fenced as data");
		assertTrue(second.has("tools"));
	}

	@Test
	void anthropicMissingKey()
	{
		CoachException e = assertThrows(CoachException.class, () -> new AnthropicProvider(new FakeHttp().client(), GSON, " ").respond(req(), new CoachTools(null)));
		assertEquals(CoachException.Kind.NO_CREDENTIALS, e.getKind());
		assertFalse(e.isRetryable());
	}

	@Test
	void anthropicHttpErrorsAreClassifiedAndNeverEchoTheKey()
	{
		Object[][] cases = {
			{401, CoachException.Kind.AUTH, false},
			{429, CoachException.Kind.RATE_LIMITED, true},
			{529, CoachException.Kind.SERVER, true},
			{400, CoachException.Kind.BAD_CONFIG, false},
		};
		for (Object[] c : cases)
		{
			String err = "{\"type\":\"error\",\"error\":{\"type\":\"x\",\"message\":\"boom\"}}";
			FakeHttp ai = new FakeHttp().respond((Integer) c[0], err).respond((Integer) c[0], err).respond((Integer) c[0], err);
			CoachException e = assertThrows(CoachException.class, () -> new AnthropicProvider(ai.client(), GSON, KEY).respond(req(), new CoachTools(null)));
			assertEquals(c[1], e.getKind(), "HTTP " + c[0]);
			assertEquals(c[2], e.isRetryable(), "HTTP " + c[0]);
			assertTrue(e.getMessage().contains("boom"));
			assertFalse(e.getMessage().contains(KEY));
		}
	}

	@Test
	void anthropicInvalidResponses()
	{
		String[] bad = {
			"not json at all",
			"[1,2,3]",
			"{\"id\":\"x\"}",
			"{\"stop_reason\":\"end_turn\",\"content\":[]}",
			"{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"text\",\"text\":\"hm\"}]}",
		};
		for (String b : bad)
		{
			FakeHttp ai = new FakeHttp().respond(200, b);
			CoachException e = assertThrows(CoachException.class, () -> new AnthropicProvider(ai.client(), GSON, KEY).respond(req(), new CoachTools(null)), b);
			assertEquals(CoachException.Kind.INVALID_RESPONSE, e.getKind(), b);
			assertTrue(e.isRetryable());
		}
	}

	@Test
	void anthropicNetworkErrors()
	{
		CoachException timeout = assertThrows(CoachException.class, () -> new AnthropicProvider(new FakeHttp().fail(new SocketTimeoutException()).client(), GSON, KEY).respond(req(), new CoachTools(null)));
		assertEquals(CoachException.Kind.NETWORK, timeout.getKind());
		assertTrue(timeout.getMessage().contains("timeout"));
		CoachException dns = assertThrows(CoachException.class, () -> new AnthropicProvider(new FakeHttp().fail(new UnknownHostException("api")).client(), GSON, KEY).respond(req(), new CoachTools(null)));
		assertEquals(CoachException.Kind.NETWORK, dns.getKind());
	}

	@Test
	void anthropicWikiDownStillAnswersWithWarning() throws Exception
	{
		FakeHttp ai = new FakeHttp()
			.respond(200, "{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"tool_use\",\"id\":\"a\",\"name\":\"wiki_page\",\"input\":{\"title\":\"Dragon Slayer I\"}}]}")
			.respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"I couldn't verify the requirements.\"}]}");
		FakeHttp wiki = new FakeHttp().fail(new UnknownHostException("oldschool.runescape.wiki"));
		CoachReply r = new AnthropicProvider(ai.client(), GSON, KEY).respond(req(), tools(wiki));
		assertEquals(1, r.getWarnings().size());
		assertTrue(r.getWarnings().get(0).contains("Couldn't reach"));
		assertTrue(ai.bodies.get(1).contains("LOOKUP_FAILED"));
		assertTrue(r.getLookedUp().isEmpty());
	}

	@Test
	void anthropicNoToolsWhenLookupsDisabled() throws Exception
	{
		FakeHttp ai = new FakeHttp().respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"ok\"}]}");
		new AnthropicProvider(ai.client(), GSON, KEY).respond(req(), new CoachTools(null));
		assertFalse(GSON.fromJson(ai.bodies.get(0), JsonObject.class).has("tools"));
	}

	@Test
	void anthropicStopsRunawayToolLoop() throws Exception
	{
		FakeHttp ai = new FakeHttp();
		String tool = "{\"stop_reason\":\"tool_use\",\"content\":[{\"type\":\"tool_use\",\"id\":\"a\",\"name\":\"wiki_search\",\"input\":{\"query\":\"q\"}}]}";
		for (int i = 0; i < AnthropicProvider.MAX_ROUNDS; i++)
		{
			ai.respond(200, tool);
		}
		ai.respond(200, "{\"stop_reason\":\"end_turn\",\"content\":[{\"type\":\"text\",\"text\":\"final\"}]}");
		FakeHttp wiki = new FakeHttp();
		for (int i = 0; i < 10; i++)
		{
			wiki.respond(200, "{\"query\":{\"search\":[]}}");
		}
		CoachReply r = new AnthropicProvider(ai.client(), GSON, KEY).respond(req(), tools(wiki));
		assertEquals("final", r.getText());
		JsonObject last = GSON.fromJson(ai.bodies.get(ai.bodies.size() - 1), JsonObject.class);
		assertEquals("none", last.getAsJsonObject("tool_choice").get("type").getAsString());
	}

	// ---------------- OpenAI-compatible ----------------

	@Test
	void openAiToolCallFlow() throws Exception
	{
		FakeHttp ai = new FakeHttp()
			.respond(200, "{\"choices\":[{\"finish_reason\":\"tool_calls\",\"message\":{\"role\":\"assistant\",\"content\":null,\"tool_calls\":[{\"id\":\"c1\",\"type\":\"function\",\"function\":{\"name\":\"ge_price\",\"arguments\":\"{\\\"item_name\\\":\\\"Lobster\\\"}\"}}]}}]}")
			.respond(200, "{\"choices\":[{\"finish_reason\":\"stop\",\"message\":{\"role\":\"assistant\",\"content\":\"Lobsters cost about 150 gp.\"}}]}");
		FakeHttp wiki = new FakeHttp()
			.respond(200, "[{\"id\":379,\"name\":\"Lobster\"}]")
			.respond(200, "{\"data\":{\"379\":{\"high\":152,\"highTime\":1791835000,\"low\":148,\"lowTime\":1791834000}}}");
		CoachReply r = new OpenAiCompatibleProvider(ai.client(), GSON, "sk-test", "https://api.openai.com/v1/").respond(req(), tools(wiki));
		assertEquals("Lobsters cost about 150 gp.", r.getText());
		assertEquals("https://api.openai.com/v1/chat/completions", ai.requests.get(0).url().toString());
		assertEquals("Bearer sk-test", ai.requests.get(0).header("Authorization"));
		assertTrue(ai.bodies.get(1).contains("\"tool_call_id\":\"c1\""));
		assertTrue(r.getLookedUp().get(0).getNote().startsWith("checked"));
	}

	@Test
	void openAiLocalServerNeedsNoKey() throws Exception
	{
		FakeHttp ai = new FakeHttp().respond(200, "{\"choices\":[{\"message\":{\"content\":\"hi\"}}]}");
		CoachReply r = new OpenAiCompatibleProvider(ai.client(), GSON, "", "http://localhost:11434/v1").respond(req(), new CoachTools(null));
		assertEquals("hi", r.getText());
		assertEquals(null, ai.requests.get(0).header("Authorization"));
	}

	@Test
	void openAiBadConfigAndInvalidResponses()
	{
		assertEquals(CoachException.Kind.BAD_CONFIG, assertThrows(CoachException.class,
			() -> new OpenAiCompatibleProvider(new FakeHttp().client(), GSON, "k", "api.openai.com").respond(req(), new CoachTools(null))).getKind());
		assertEquals(CoachException.Kind.NO_CREDENTIALS, assertThrows(CoachException.class,
			() -> new OpenAiCompatibleProvider(new FakeHttp().client(), GSON, "", "https://openrouter.ai/api/v1").respond(req(), new CoachTools(null))).getKind());
		for (String b : new String[]{"{\"choices\":[]}", "{\"choices\":[{\"message\":{\"content\":\"\"}}]}", "{}"})
		{
			FakeHttp ai = new FakeHttp().respond(200, b);
			assertEquals(CoachException.Kind.INVALID_RESPONSE, assertThrows(CoachException.class,
				() -> new OpenAiCompatibleProvider(ai.client(), GSON, "k", "https://x.test/v1").respond(req(), new CoachTools(null)), b).getKind());
		}
	}

	@Test
	void openAiMalformedToolArgumentsAreReportedToModel() throws Exception
	{
		FakeHttp ai = new FakeHttp()
			.respond(200, "{\"choices\":[{\"message\":{\"tool_calls\":[{\"id\":\"c1\",\"function\":{\"name\":\"wiki_search\",\"arguments\":\"{not json\"}}]}}]}")
			.respond(200, "{\"choices\":[{\"message\":{\"content\":\"done\"}}]}");
		CoachReply r = new OpenAiCompatibleProvider(ai.client(), GSON, "k", "https://x.test/v1").respond(req(), tools(new FakeHttp()));
		assertEquals("done", r.getText());
		assertTrue(ai.bodies.get(1).contains("BAD_ARGUMENTS"));
	}

	@Test
	void transientServerErrorCarriesRetryHint()
	{
		FakeHttp ai = new FakeHttp().respond(503, "{\"error\":{\"message\":\"overloaded\"}}");
		CoachException e = org.junit.jupiter.api.Assertions.assertThrows(CoachException.class,
			() -> new OpenAiCompatibleProvider(ai.client(), GSON, "k", "https://x.test/v1").respond(req(), new CoachTools(null)));
		assertTrue(e.isServerBusy());
		assertEquals(3.0, e.getRetryAfterSeconds(), 0.001);
		assertEquals(1, ai.requests.size(), "provider never waits or retries by itself");
	}

	@Test
	void openAiNeverSendsToolChoiceNoneAndStopsRunawayLookups() throws Exception
	{
		String toolCall = "{\"choices\":[{\"message\":{\"tool_calls\":[{\"id\":\"c\",\"function\":{\"name\":\"wiki_search\",\"arguments\":\"{\\\"query\\\":\\\"x\\\"}\"}}]}}]}";
		FakeHttp ai = new FakeHttp();
		for (int i = 0; i <= 3; i++)
		{
			ai.respond(200, toolCall);
		}
		ai.respond(200, "{\"choices\":[{\"message\":{\"content\":\"final\"}}]}");
		FakeHttp wiki = new FakeHttp();
		for (int i = 0; i < 5; i++)
		{
			wiki.respond(200, "{\"query\":{\"search\":[]}}");
		}
		CoachRequest r = req().toBuilder().compact(true).build();
		assertEquals("final", new OpenAiCompatibleProvider(ai.client(), GSON, "k", "https://api.groq.com/openai/v1").respond(r, tools(wiki)).getText());
