class WebSearchClientTest
{
	private static final Gson GSON = new Gson();

	private static WebSearchClient client(FakeHttp f, WebSearchClient.Backend b, String key)
	{
		return new WebSearchClient(f.client(), GSON, b, key);
	}

	@Test
	void serperReturnsGoogleResultsAndSendsKeyHeader() throws Exception
	{
		FakeHttp f = new FakeHttp().respond(200, "{\"answerBox\":{\"snippet\":\"Varlamore part 3 released\"},"
			+ "\"organic\":[{\"title\":\"OSRS news\",\"link\":\"https://secure.runescape.com/m=news/x\",\"snippet\":\"Patch notes\"},"
			+ "{\"title\":\"bad\",\"link\":\"javascript:alert(1)\",\"snippet\":\"x\"}]}");
		LookupResult r = client(f, WebSearchClient.Backend.SERPER_GOOGLE, "serper-key").search("osrs update");
		assertEquals("serper-key", f.requests.get(0).header("X-API-KEY"));
		assertEquals("https://google.serper.dev/search", f.requests.get(0).url().toString());
		assertTrue(f.bodies.get(0).contains("\"q\":\"osrs update\""));
		assertTrue(r.getText().contains("Google answer box: Varlamore part 3 released"));
		assertEquals(1, r.getSources().size(), "non-http links are dropped");
	}

	@Test
	void braveParsesResults() throws Exception
	{
		FakeHttp f = new FakeHttp().respond(200, "{\"type\":\"search\",\"web\":{\"results\":[{\"title\":\"Reddit thread\",\"url\":\"https://www.reddit.com/r/2007scape/x\",\"description\":\"<strong>Best</strong> f2p money\"}]}}");
		LookupResult r = client(f, WebSearchClient.Backend.BRAVE, "brave-key").search("f2p money");
		assertEquals("brave-key", f.requests.get(0).header("X-Subscription-Token"));
		assertEquals("f2p money", f.requests.get(0).url().queryParameter("q"));
		assertTrue(r.getText().contains("Best f2p money"), r.getText());
		assertEquals("https://www.reddit.com/r/2007scape/x", r.getSources().get(0).getUrl());
	}

	@Test
	void braveEmptyResultsAreFine() throws Exception
	{
		LookupResult r = client(new FakeHttp().respond(200, "{\"type\":\"search\"}"), WebSearchClient.Backend.BRAVE, "k").search("zzzz");
		assertTrue(r.getText().contains("(no results)"));
	}

	@Test
	void failuresAreLookupExceptions()
	{
		assertThrows(LookupException.class, () -> client(new FakeHttp(), WebSearchClient.Backend.SERPER_GOOGLE, " ").search("x"));
		LookupException auth = assertThrows(LookupException.class, () -> client(new FakeHttp().respond(403, "{}"), WebSearchClient.Backend.SERPER_GOOGLE, "k").search("x"));
		assertTrue(auth.getMessage().contains("key rejected"));
		LookupException quota = assertThrows(LookupException.class, () -> client(new FakeHttp().respond(429, "{}"), WebSearchClient.Backend.BRAVE, "k").search("x"));
		assertTrue(quota.getMessage().contains("quota"));
		assertThrows(LookupException.class, () -> client(new FakeHttp().fail(new UnknownHostException()), WebSearchClient.Backend.BRAVE, "k").search("x"));
		assertThrows(LookupException.class, () -> client(new FakeHttp().respond(200, "{\"oops\":1}"), WebSearchClient.Backend.SERPER_GOOGLE, "k").search("x"));
	}

	@Test
	void htmlToTextDropsScriptsAndTags()
	{
		String t = WebSearchClient.htmlToText("<html><head><style>p{}</style><script>steal()</script></head><body><nav>menu</nav><h1>Guide</h1><p>Use a <b>bronze axe</b>&nbsp;first.</p></body></html>");
		assertFalse(t.contains("steal"));
		assertFalse(t.contains("menu"));
		assertTrue(t.contains("Guide"));
		assertTrue(t.contains("Use a bronze axe first."), t);
	}

	@Test
	void webPageOnlyOpensUrlsFromSearchResults()
	{
		FakeHttp f = new FakeHttp()
			.respond(200, "{\"organic\":[{\"title\":\"Guide\",\"link\":\"https://example.com/guide\",\"snippet\":\"s\"}]}")
			.respond(200, "<html><body><p>Woodcutting tips</p></body></html>");
		CoachTools tools = new CoachTools(null, client(f, WebSearchClient.Backend.SERPER_GOOGLE, "k"));

		JsonObject bad = new JsonObject();
		bad.addProperty("url", "http://192.168.1.1/admin");
		assertTrue(tools.execute("web_page", bad).startsWith("NOT_ALLOWED"));

		JsonObject q = new JsonObject();
		q.addProperty("query", "osrs woodcutting");
		String search = tools.execute("web_search", q);
		assertTrue(search.contains("general-web"), "web results are marked lower-trust");
		assertTrue(tools.sources().isEmpty(), "search hits are not listed as fetched pages");

		JsonObject ok = new JsonObject();
		ok.addProperty("url", "https://example.com/guide");
		String page = tools.execute("web_page", ok);
		assertTrue(page.contains("Woodcutting tips"));
		assertEquals("https://example.com/guide", tools.sources().get(0).getUrl());

		JsonObject wiki = new JsonObject();
		wiki.addProperty("query", "x");
		assertTrue(tools.execute("wiki_search", wiki).startsWith("LOOKUP_UNAVAILABLE"), "wiki off stays off");
		assertEquals(2, tools.specs().size());
	}
}

package com.osrscoach.research;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import com.osrscoach.ai.CoachPrompt;
import org.junit.jupiter.api.Test;

class WikiCleanTest
{
	@Test
	void stripsNoiseKeepsFactsAndCoordinates()
	{
		String raw = "{{External|rs}}\n{{Has quick guide}}\n{{Infobox Quest\n|image = [[File:Pip.png|300px]]\n|release = [[1 Jan]]\n|members = Yes\n}}\n"
			+ "'''Priest in Peril''' is a [[quest]] in [[Varrock|the city]].<ref>Patch notes</ref>\n<!-- hidden -->\n\n\n\n"
			+ "|startmap = 3221,3473\n{{Map|x:3423,y:3461}}\n[[Category:Quests]]";
		String c = WikiClient.cleanWikitext(raw);
		assertFalse(c.contains("External") || c.contains("File:") || c.contains("Patch notes") || c.contains("hidden") || c.contains("Category:"), c);
		assertFalse(c.contains("release ="), c);
		assertTrue(c.contains("Priest in Peril is a quest in the city."), c);
		assertTrue(c.contains("startmap = 3221,3473") && c.contains("x:3423,y:3461"), "coordinates must survive for map markers");
		assertTrue(c.contains("members = Yes"));
		assertFalse(c.contains("\n\n\n"));
	}

	@Test
	void stepByStepPromptSwitch()
	{
		assertTrue(CoachPrompt.system("ctx", true, false, true).contains("STEP BY STEP"));
		assertFalse(CoachPrompt.system("ctx", true, false, false).contains("STEP BY STEP"));
	}
}

package com.osrscoach.research;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import com.google.gson.Gson;
import com.osrscoach.FakeHttp;
import com.osrscoach.MockData;
import java.net.SocketTimeoutException;
import java.time.Clock;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class WikiClientTest
{
	private static WikiClient wiki(FakeHttp f)
	{
		return new WikiClient(f.client(), new Gson(), Clock.fixed(MockData.NOW, ZoneOffset.UTC), WikiClient.WIKI, WikiClient.PRICES);
	}

	@Test
	void searchParsesResultsAndSetsUserAgent() throws Exception
	{
		FakeHttp f = new FakeHttp().respond(200, "{\"query\":{\"search\":[{\"title\":\"Cook's Assistant\",\"snippet\":\"<span class=\\\"searchmatch\\\">Cook</span>&#039;s first quest\"}]}}");
		LookupResult r = wiki(f).search("cook");
		assertEquals(1, r.getSources().size());
		assertEquals("https://oldschool.runescape.wiki/w/Cook's_Assistant", r.getSources().get(0).getUrl());
		assertTrue(r.getText().contains("Cook's first quest"), r.getText());
		assertTrue(f.requests.get(0).header("User-Agent").contains("osrs-coach"));
	}

	@Test
	void pageTruncatesAndCites() throws Exception
	{
		StringBuilder big = new StringBuilder();
		for (int i = 0; i < 2000; i++)
		{
			big.append("requirement ");
		}
		FakeHttp f = new FakeHttp().respond(200, "{\"parse\":{\"title\":\"Dragon Slayer I\",\"wikitext\":\"" + big + "\"}}");
		LookupResult r = wiki(f).page("Dragon Slayer");
		assertTrue(r.getText().contains("[...page truncated...]"));
		assertEquals("Dragon Slayer I", r.getSources().get(0).getTitle());
	}

	@Test
	void missingPageIsNotAnError() throws Exception
	{
		FakeHttp f = new FakeHttp().respond(200, "{\"error\":{\"code\":\"missingtitle\",\"info\":\"The page you specified doesn't exist.\"}}");
		LookupResult r = wiki(f).page("Nope");
		assertTrue(r.getText().contains("not found"));
		assertTrue(r.getSources().isEmpty());
	}

	@Test
	void priceShowsCheckedTime() throws Exception
	{
		FakeHttp f = new FakeHttp()
			.respond(200, "[{\"id\":379,\"name\":\"Lobster\"}]")
			.respond(200, "{\"data\":{\"379\":{\"high\":152,\"highTime\":1791835000,\"low\":148,\"lowTime\":1791834000}}}");
		LookupResult r = wiki(f).price("lobster");
		assertTrue(r.getText().contains("152 gp"), r.getText());
		assertTrue(r.getText().contains("checked 2026-10-12 20:00 UTC"), r.getText());
		assertEquals("checked 2026-10-12 20:00 UTC", r.getSources().get(0).getNote());
	}

	@Test
	void unknownItemNoGuess() throws Exception
	{
		FakeHttp f = new FakeHttp().respond(200, "[{\"id\":379,\"name\":\"Lobster\"}]");
		WikiClient w = wiki(f);
		assertTrue(w.price("Golden lobster").getText().startsWith("No tradeable item"));
		assertNull(w.findItemId("nothing"));
	}

	@Test
	void networkAndServerFailuresBecomeLookupExceptions()
	{
		assertThrows(LookupException.class, () -> wiki(new FakeHttp().fail(new SocketTimeoutException())).search("x"));
		assertThrows(LookupException.class, () -> wiki(new FakeHttp().respond(503, "down")).search("x"));
		assertThrows(LookupException.class, () -> wiki(new FakeHttp().respond(200, "<html>not json")).search("x"));
		assertThrows(LookupException.class, () -> wiki(new FakeHttp().respond(200, "{\"unexpected\":1}")).search("x"));
	}
}

package com.osrscoach.ui;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.Test;

class MarkdownTest
{
	@Test
	void boldLinksAndBreaks()
	{
		String h = Markdown.toHtml("**Next step:** see [Cook's Assistant](https://oldschool.runescape.wiki/w/Cook's_Assistant)\n- bring an egg");
		assertTrue(h.contains("<b>Next step:</b>"), h);
		assertTrue(h.contains("<a href=\"https://oldschool.runescape.wiki/w/Cook's_Assistant\">Cook's Assistant</a>"), h);
		assertTrue(h.contains("<br>• bring an egg"), h);
	}

	@Test
	void bareUrlsLinkedOnce()
	{
		String h = Markdown.toHtml("Sources: https://oldschool.runescape.wiki/w/Fishing");
		assertEquals(1, h.split("<a ").length - 1, h);
	}

	@Test
	void modelCannotInjectHtml()
	{
		String h = Markdown.toHtml("<img src=x onerror=alert(1)><script>x</script>[click](javascript:alert(1))");
		assertFalse(h.contains("<img"));
		assertFalse(h.contains("<script"));
		assertFalse(h.contains("href=\"javascript"));
	}
}
